import { execFile } from 'node:child_process';
import fs from 'node:fs';
import { promisify } from 'node:util';
import type { Page } from '@playwright/test';
import { test, expect } from '../fixtures.js';
import { appUrl, downloadPath } from './acts.js';

// Exercises web-app/src/downloadSink.ts on its own, with no platform: the page
// imports the module from the dev server and streams generated bytes through
// it. Set SINK_TEST_BYTES to try a large file, and SINK_TEST_MIBPS to pace the
// source so the download outlives the browser's service worker timeouts. For
// example, 12 GiB at 32 MiB/s takes about six and a half minutes:
//
//   SINK_TEST_BYTES=12884901888 SINK_TEST_MIBPS=32 PLAYWRIGHT_TESTS_TO_RUN=sink \
//     npx playwright test --project chromium
//
// Not --project firefox: Playwright's Firefox keeps every download in memory.

const largeBytes = Number(process.env.SINK_TEST_BYTES ?? 0);
const mibPerSecond = Number(process.env.SINK_TEST_MIBPS ?? 0);
const sinkModule = `${appUrl}src/downloadSink.ts`;
// Byte at offset n is n % PERIOD, so any dropped, repeated or reordered chunk
// shows up as a mismatch.
const PERIOD = 251;

type StreamOptions = {
  // Abort once this many bytes have been produced, or this long after starting.
  abortAfter?: number;
  abortAfterMs?: number;
  mibps?: number;
};

async function streamDownload(
  page: Page,
  bytes: number,
  { abortAfter, abortAfterMs, mibps = 0 }: StreamOptions = {}
) {
  return page.evaluate(
    async ({ sinkModule, bytes, abortAfter, abortAfterMs, mibps, PERIOD }) => {
      const { toFile } = await import(sinkModule);
      const chunkSize = 2 ** 20;
      const pattern = new Uint8Array(chunkSize + PERIOD).map((_, i) => i % PERIOD);
      const abort = new AbortController();
      if (abortAfterMs !== undefined) {
        setTimeout(() => abort.abort(new Error('test abort')), abortAfterMs);
      }
      let offset = 0;
      const started = performance.now();
      const source = new ReadableStream<Uint8Array>({
        async pull(controller) {
          if (mibps) {
            const due = started + (offset / 2 ** 20 / mibps) * 1000;
            await new Promise((resolve) => setTimeout(resolve, due - performance.now()));
          }
          if (abortAfter !== undefined && offset >= abortAfter) {
            abort.abort(new Error('test abort'));
          }
          const n = Math.min(chunkSize, bytes - offset);
          if (n <= 0) {
            controller.close();
            return;
          }
          const start = offset % PERIOD;
          controller.enqueue(pattern.subarray(start, start + n));
          offset += n;
        },
      });
      try {
        return await toFile(source, `sink-${bytes}.bin`, { signal: abort.signal });
      } catch (e) {
        return `rejected: ${e instanceof Error ? e.message : String(e)}`;
      }
    },
    { sinkModule, bytes, abortAfter, abortAfterMs, mibps, PERIOD }
  );
}

async function expectPattern(path: string, bytes: number) {
  let offset = 0;
  for await (const chunk of fs.createReadStream(path) as AsyncIterable<Buffer>) {
    for (let i = 0; i < chunk.length; i++) {
      if (chunk[i] !== (offset + i) % PERIOD) {
        throw new Error(`byte ${offset + i} is ${chunk[i]}, expected ${(offset + i) % PERIOD}`);
      }
    }
    offset += chunk.length;
  }
  expect(offset).toBe(bytes);
}

/**
 * Resident memory of this project's browser processes, sampled once a second.
 * Only meaningful when one project runs at a time. For stock Firefox only the
 * parent process is counted: its content processes can't be told apart from
 * those of a Firefox the user has open. The parent is where downloads are
 * written, though.
 */
async function sampleBrowserMemory(browserName: string) {
  const ours =
    browserName === '_bidiFirefox'
      ? (line: string) => line.includes('playwright__bidiFirefox')
      : (line: string) =>
          line.includes('ms-playwright') && line.toLowerCase().includes(browserName);
  const sample = async () => {
    const { stdout } = await promisify(execFile)('ps', ['-ax', '-o', 'rss=,command=']);
    return stdout
      .split('\n')
      .filter(ours)
      .reduce((sum, line) => sum + parseInt(line), 0);
  };
  const baselineKiB = await sample();
  let peakKiB = baselineKiB;
  const timer = setInterval(async () => {
    peakKiB = Math.max(peakKiB, await sample());
  }, 1000);
  return () => {
    clearInterval(timer);
    return { baselineKiB, peakKiB };
  };
}

const gib = (kib: number) => `${(kib / 2 ** 20).toFixed(2)} GiB`;

// The hook below can wait out a cold worker install, and several tests wait
// out toFile's 5 s worker or 10 s start timeouts.
test.describe.configure({ timeout: 30_000 });

test.beforeEach(async ({ page, serviceWorkers }) => {
  page.on('pageerror', (err) => console.error(err));
  await page.goto(appUrl);
  // A cold runner can take longer to install the worker than toFile waits.
  if (serviceWorkers === 'allow') {
    await page.evaluate(() => navigator.serviceWorker.ready);
  }
});

test('streams a download through the service worker', async ({ page }) => {
  const bytes = 3 * 2 ** 20 + 17;
  const downloadPromise = page.waitForEvent('download');
  const strategy = await streamDownload(page, bytes);
  const download = await downloadPromise;
  expect(download.suggestedFilename()).toBe(`sink-${bytes}.bin`);
  const path = await downloadPath(download);
  await expectPattern(path, bytes);
  expect(strategy).toBe('service-worker');
});

test('a download that outlasts the start timeout completes', async ({ page }) => {
  // Paced past toFile's 10 s start timeout, so this fails if the worker stops
  // reporting that the download started.
  const bytes = 12 * 2 ** 20;
  const downloadPromise = page.waitForEvent('download');
  const strategy = await streamDownload(page, bytes, { mibps: 1 });
  const download = await downloadPromise;
  await expectPattern(await downloadPath(download), bytes);
  expect(strategy).toBe('service-worker');
});

test('an abort fails the download instead of truncating it', async ({ page, browserName }) => {
  // Firefox does error the download, but Playwright's Firefox never settles
  // download.failure() for it.
  test.skip(browserName === 'firefox', 'Playwright does not report the failed download');
  const downloadPromise = page.waitForEvent('download');
  // The worker queues 4 MiB before the browser starts reading, so aborting at
  // 8 MiB happens after the download has started.
  const result = await streamDownload(page, 64 * 2 ** 20, { abortAfter: 8 * 2 ** 20 });
  expect(result).toMatch(/^rejected: .*test abort/);
  const download = await downloadPromise;
  expect(await download.failure()).not.toBeNull();
});

// Keeps the download's iframe request from ever reaching the worker.
async function blockFrames(page: Page) {
  await page.evaluate(() => {
    const csp = document.createElement('meta');
    csp.httpEquiv = 'Content-Security-Policy';
    csp.content = "frame-src 'none'";
    document.head.append(csp);
  });
}

for (const bytes of [2 ** 20, 16 * 2 ** 20]) {
  test(`a blocked download fails instead of hanging (${bytes} bytes)`, async ({ page }) => {
    // Below the worker's 4 MiB queue, every byte fits in it without the
    // browser reading any, so this once reported success with no file; above
    // it, the pipe waited forever for credit.
    await blockFrames(page);
    const result = await streamDownload(page, bytes);
    expect(result).toMatch(/^rejected: The download never reached the service worker/);
  });
}

test('an abort still works once the source has closed', async ({ page }) => {
  // The whole source fits in the worker's queue, so the sink is already
  // waiting in close(), where pipeTo no longer watches its signal.
  await blockFrames(page);
  const started = Date.now();
  const result = await streamDownload(page, 2 ** 20, { abortAfterMs: 500 });
  expect(result).toMatch(/^rejected: .*test abort/);
  expect(Date.now() - started).toBeLessThan(5_000);
});

test.describe('without a service worker', () => {
  test.use({ serviceWorkers: 'block' });

  test('falls back to an in-memory Blob', async ({ page }) => {
    const bytes = 2 ** 20 + 17;
    const downloadPromise = page.waitForEvent('download');
    const strategy = await streamDownload(page, bytes);
    const download = await downloadPromise;
    await expectPattern(await downloadPath(download, 'blob'), bytes);
    expect(strategy).toBe('blob');
  });
});

test('large download keeps memory flat', async ({ page, browserName }) => {
  test.skip(!largeBytes, 'set SINK_TEST_BYTES to run');
  test.setTimeout(0);
  const stopSampling = await sampleBrowserMemory(browserName);
  const started = Date.now();
  const downloadPromise = page.waitForEvent('download');
  const strategy = await streamDownload(page, largeBytes, { mibps: mibPerSecond });
  const download = await downloadPromise;
  const path = await downloadPath(download);
  const { baselineKiB, peakKiB } = stopSampling();
  try {
    expect(fs.statSync(path).size).toBe(largeBytes);
  } finally {
    fs.unlinkSync(path);
  }
  console.log(
    `[${browserName}] ${largeBytes.toLocaleString()} bytes via ${strategy} in ` +
      `${((Date.now() - started) / 1000).toFixed(0)} s; ` +
      `browser RSS ${gib(baselineKiB)} before, ${gib(peakKiB)} peak`
  );
});
